import{_ as o,l,o as e,c as s,v as t,p as n,x as i,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"时间片与公平调度","description":"","frontmatter":{"title":"时间片与公平调度","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/timeslice-cfs.md","filePath":"cs/timeslice-cfs.md","lastUpdated":1789023840000}'),E={name:"cs/timeslice-cfs.md"};function _(h,a,m,u,B,C){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="时间片与公平调度" tabindex="-1">时间片与公平调度 <a class="header-anchor" href="#时间片与公平调度" aria-label="Permalink to &quot;时间片与公平调度&quot;">​</a></h1><div class="epigraph"><p>完全公平调度试图让每条可运行任务分到与其权重成比例的 CPU 时间。</p><footer>—— 据 Linux CFS 设计直觉；Silberschatz et al. 对轮转与公平的整理</footer></div><p><a href="/cs/pi-pcp">上一课</a>给出响应与公平等尺子。轮转用时间片改善响应，但仍把每条线程当同等的「下一个量子」。缺口是：交互与后台、不同 nice，需要<strong>按权重摊时间</strong>，而不是固定队列转圈。本课用时间片与 CFS 的虚拟运行时间当直觉，不当成内核源码课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯 FCFS 响应差；固定时间片轮转公平但无权重：后台编译与前台击键抢同一圈。缺口不是新的指标定义，而是一种分配：在任意窗口里，线程 \\(i\\) 获得的 CPU 份额接近 \\(w_i/\\sum w\\)。实现上，每次选「至今吃得最少（按权重折算）」的那条。</p><p>本课不把红黑树结点布局、<code>vruntime</code> 溢出细节写完，只钉这套直觉。</p><p><span class="marginnote">CFS 用虚拟运行时间：实际跑 \\(\\Delta t\\) 的线程，其 <code>vruntime</code> 增加约 \\(\\Delta t \\cdot w_0/w_i\\)。权重越大，虚拟时钟走得越慢，越容易被再次选中。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>时钟中断或主动让出时进入调度：比较可运行线程的虚拟运行时间，切到最小者；给它一段时间片（或直到它阻塞、直到别人的虚拟时间追上）。时间片不是魔法常数：太短切换开销压过吞吐，太长响应变差——尺子仍是上一课那些。</p>',9)),(e(),n(p,null,{default:i(()=>[c(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20READY%5B%22%E5%B0%B1%E7%BB%AA%E7%BA%BF%E7%A8%8B%22%5D%20--%3E%20VR%5B%22%E6%8C%89%E6%9D%83%E9%87%8D%E6%8A%98%E7%AE%97%E7%9A%84%E8%99%9A%E6%8B%9F%E6%97%B6%E9%97%B4%22%5D%0A%20%20VR%20--%3E%20PICK%5B%22%E9%80%89%E6%9C%80%E5%B0%8F%E8%80%85%E4%B8%8A%20CPU%22%5D%0A%20%20PICK%20--%3E%20TICK%5B%22%E8%B7%91%E4%B8%80%E6%AE%B5%E6%97%B6%E9%97%B4%E5%86%8D%E6%AF%94%E8%BE%83%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>阻塞的线程不累积「亏欠到无限」的简单模型即可：醒来时把虚拟时间接到当前最小附近，避免一下子垄断 CPU。Linux 的具体补偿是实现，主干只要求不饿死、不让睡很久的人醒来瞬间吞掉全部核心。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公平是对<strong>可运行</strong>集合而言：在磁盘上睡的人不应靠「睡着也涨份额」抢走交互。时间片把上一课的响应指标变成可调旋钮；权重把「公平」从人数均等改成份额均等。上下文切换次数随可运行集合与片长变化，所以公平策略仍付切换税。</p><p>本课不处理截止时间：公平摊时间可以让所有人错过期限。那是下一课实时调度的对照。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是 Linux 内核实验指导，不保证与某主线版本的字段同名。不引入实时策略（<code>SCHED_FIFO</code>）与 deadline 调度。也不把多核共享缓存的调度写成 NUMA 课。</p><p>交互性启发式（睡眠补偿）是实现，不是公平份额的定义；本课以虚拟时间为准。</p><p>后课默认：通用分时按权重摊 CPU，用虚拟时间近似。有硬期限的任务不能靠这一套，下一课对照。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>时间片改善响应；权重把公平从「人次」改成「份额」。</li><li>CFS 直觉：跑得越少（折算后）越先上。</li><li>实时期限是另一套目标，不能从 vruntime 推出。</li><li>出处：Silberschatz et al., <em>OSC</em>；Linux CFS 设计讨论（Molnar 等），作直觉而非源码转写。</li></ul>',10))])}const S=o(E,[["render",_]]);export{A as __pageData,S as default};
